sample:
# alias とリージョンの対応表を locals で整理します。
# provider = aws.virginia が付いたリソースは us-east-1 に作られます。
locals {
  provider_regions = {
    default  = "ap-northeast-1"
    virginia = "us-east-1"
  }
}

output "default_region" {
  value = local.provider_regions["default"]
}

output "virginia_region" {
  value = local.provider_regions["virginia"]
}

exercise.starter:
locals {
  provider_regions = {
    # alias => region の対応を書く
  }
}

exercise.answer:
# alias なしの設定を default というキーで持つと対応表として整理しやすいです。
# cdn には provider = aws.virginia が付いているので、作られる先は
# map の virginia キーの値 us-east-1 です。
locals {
  provider_regions = {
    default  = "ap-northeast-1"
    osaka    = "ap-northeast-3"
    virginia = "us-east-1"
  }
}

output "alias_count" {
  value = length(local.provider_regions)
}

output "aliases" {
  value = join(", ", keys(local.provider_regions))
}

output "cert_region" {
  value = local.provider_regions["virginia"]
}
